def tau_n12(n):
    """Calculates tau(n^12)"""
    if n == 1:
        return 1

    # Prime factorization of n: n = p1^a1 * p2^a2 * ...
    factors = {}
    temp = n
    d = 2
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1

    # tau(n^12) = product of (12*ai + 1)
    result = 1
    for p, a in factors.items():
        result *= (12 * a + 1)
    return result

